input.command:
mkdir -p cmd/syscli internal/platform && cat > cmd/syscli/main.go <<'EOF'
// Command syscli is a CLI tool that uses OS-level system calls not exposed
// by the Go standard library.
package main

import (
	"fmt"
	"os"

	"github.com/example/syscli/internal/platform"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "syscli:", err)
		os.Exit(1)
	}
}

func run() error {
	release, err := platform.KernelRelease()
	if err != nil {
		return fmt.Errorf("kernel release: %w", err)
	}
	fmt.Println("kernel:", release)

	cols, rows, err := platform.TerminalSize(os.Stdout)
	if err != nil {
		fmt.Println("terminal: not a terminal")
	} else {
		fmt.Printf("terminal: %dx%d\n", cols, rows)
	}
	return nil
}
EOF
cat > internal/platform/platform.go <<'EOF'
// Package platform wraps low-level, OS-specific system calls behind a
// portable API. Each supported OS has its own implementation file selected
// by the Go toolchain's filename suffix (_linux.go, _darwin.go, _windows.go)
// or by //go:build constraints.
//
// Use golang.org/x/sys/unix and golang.org/x/sys/windows rather than the
// frozen standard library "syscall" package.
package platform

import "errors"

// ErrUnsupported is returned on operating systems without an implementation.
var ErrUnsupported = errors.New("platform: operation not supported on this OS")
EOF
cat > internal/platform/terminal_unix.go <<'EOF'
//go:build linux || darwin

package platform

import (
	"os"

	"golang.org/x/sys/unix"
)

// TerminalSize returns the width and height of the terminal attached to f.
func TerminalSize(f *os.File) (cols, rows int, err error) {
	ws, err := unix.IoctlGetWinsize(int(f.Fd()), unix.TIOCGWINSZ)
	if err != nil {
		return 0, 0, err
	}
	return int(ws.Col), int(ws.Row), nil
}
EOF
cat > internal/platform/kernel_linux.go <<'EOF'
package platform

import "golang.org/x/sys/unix"

// KernelRelease returns the running kernel's release string (uname -r).
func KernelRelease() (string, error) {
	var u unix.Utsname
	if err := unix.Uname(&u); err != nil {
		return "", err
	}
	return unix.ByteSliceToString(u.Release[:]), nil
}
EOF
cat > internal/platform/kernel_darwin.go <<'EOF'
package platform

import "golang.org/x/sys/unix"

// KernelRelease returns the running Darwin kernel's release string.
func KernelRelease() (string, error) {
	return unix.Sysctl("kern.osrelease")
}
EOF
cat > internal/platform/platform_windows.go <<'EOF'
package platform

import (
	"fmt"
	"os"

	"golang.org/x/sys/windows"
)

// KernelRelease returns the Windows version as major.minor.build.
// RtlGetVersion reports the true version regardless of app manifest.
func KernelRelease() (string, error) {
	v := windows.RtlGetVersion()
	return fmt.Sprintf("%d.%d.%d", v.MajorVersion, v.MinorVersion, v.BuildNumber), nil
}

// TerminalSize returns the width and height of the console attached to f.
func TerminalSize(f *os.File) (cols, rows int, err error) {
	var info windows.ConsoleScreenBufferInfo
	if err := windows.GetConsoleScreenBufferInfo(windows.Handle(f.Fd()), &info); err != nil {
		return 0, 0, err
	}
	w := info.Window
	return int(w.Right-w.Left) + 1, int(w.Bottom-w.Top) + 1, nil
}
EOF
cat > internal/platform/platform_other.go <<'EOF'
//go:build !linux && !darwin && !windows

package platform

import "os"

func KernelRelease() (string, error) { return "", ErrUnsupported }

func TerminalSize(*os.File) (cols, rows int, err error) { return 0, 0, ErrUnsupported }
EOF
cat > internal/platform/platform_test.go <<'EOF'
package platform

import "testing"

func TestKernelRelease(t *testing.T) {
	r, err := KernelRelease()
	if err == ErrUnsupported {
		t.Skip(err)
	}
	if err != nil {
		t.Fatal(err)
	}
	if r == "" {
		t.Fatal("empty kernel release")
	}
	t.Log(r)
}
EOF
cat > Makefile <<'EOF'
PLATFORMS := linux/amd64 linux/arm64 darwin/amd64 darwin/arm64 windows/amd64 windows/arm64

.PHONY: build test vet cross
build:
	go build -o bin/syscli ./cmd/syscli

test:
	go test ./...

vet:
	@for p in $(PLATFORMS); do \
		echo "vet $$p"; GOOS=$${p%/*} GOARCH=$${p#*/} go vet ./... || exit 1; \
	done

cross:
	@for p in $(PLATFORMS); do \
		os=$${p%/*}; arch=$${p#*/}; ext=; [ $$os = windows ] && ext=.exe; \
		echo "build $$p"; \
		CGO_ENABLED=0 GOOS=$$os GOARCH=$$arch go build -o bin/syscli-$$os-$$arch$$ext ./cmd/syscli || exit 1; \
	done
EOF
printf 'bin/\n' > .gitignore
go mod tidy && gofmt -l . ; make test vet cross && go run ./cmd/syscli && ls bin

